Point"]=0,["name"]=[[映雪阁]],["permission"]=0,["fullName"]=[[映雪阁(fb616_41)]],["enterable"]=1,["up"]=[[fb616_38]],["dsc"]=[[忽梦少年江湖事，醉下试剑春映雪。蓬莱岛四季无雪，映雪阁名映雪，实则是满植雪白海棠花，花落时如冬日大雪，阁内一片洁白。]],["down"]=[[fb616_44]],["visible"]=1,["dirIndex"]=0,["unit1"]=[[npc01]],["canLeave"]=1,["id"]=[[fb616_41]],["mapHide"]=0},{["operations"]={},["rightUp"]=[[fb616_47]],["connectPoint"]=0,["name"]=[[花船口岸]],["permission"]=0,["enterable"]=1,["stepMusic"]=[[jiaobu]],["dsc"]=[[阁东三十里海边有漏天岩，飞岩下覆，细孔万余，四时水滴如漏，蔚为奇观。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[花船口岸(fb616_48)]],["canLeave"]=1,["id"]=[[fb616_48]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb616_20]],["connectPoint"]=0,["name"]=[[挂鱼台]],["permission"]=0,["left"]=[[fb616_18]],["enterable"]=1,["up"]=[[fb616_15]],["dsc"]=[[昔日俞岛主初至蓬莱岛时，食不果腹，衣不蔽体。幸好此处有淡水，而岛上渔猎资源充足，于是俞岛主便将捕来的鱼挂在此处，用淡水清洗烹饪，故称挂鱼台。]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[挂鱼台(fb616_19)]],["canLeave"]=1,["id"]=[[fb616_19]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb616_19]],["connectPoint"]=0,["name"]=[[桃林]],["permission"]=0,["left"]=[[fb616_13]],["fullName"]=[[桃林(fb616_18)]],["enterable"]=1,["dsc"]=[[这是一片很小的桃花林，左不过十数棵桃树，中间有一条曲曲折折的石子小路，两旁篱笆上爬满青藤。恰如世外桃源，落花如雨。]],["down"]=[[fb616_24]],["visible"]=1,["unit4"]=[[25cyshoppenglai]],["dirIndex"]=0,["unit3"]=[[22penglaicynpc]],["unit2"]=[[npc08]],["unit1"]=[[shengwang19]],["canLeave"]=1,["id"]=[[fb616_18]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["right"]=[[fb616_16]],["connectPoint"]=0,["name"]=[[村道]],["permission"]=0,["enterable"]=1,["dsc"]=[[绿荫村道，两侧用翠竹和细绳绑出了一条篱笆小路，因岛内遍植桃树，所以花瓣纷落，铺的满地都是。]],["down"]=[[fb616_19]],["visible"]=1,["dirIndex"]=0,["fullName"]=[[村道(fb616_15)]],["canLeave"]=1,["id"]=[[fb616_15]],["mapHide"]=0},{["operations"]={},["stepMusic"]=[[jiaobu]],["connectPoint"]=0,["name"]=[[村舍]],["permission"]=0,["enterable"]=1,["dsc"]=[[一间茅草村舍，屋檐上新筑了一个鸟窝，舍前一棵瘦小的桃花树，树下放着两坛香醇的美酒，酒香混着花香，一派清幽。]],["down"]=[[fb616_16]],["visible"]=1,["dirIndex"]=0,["fullName"]=